import{z as i,x as n,o as E,c as d,q as s,j as r,D as a,d as t,s as l,S as A}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"零拷贝网络","description":"","frontmatter":{"title":"零拷贝网络","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/zero-copy-network.md","filePath":"cs/zero-copy-network.md","lastUpdated":1791063341000}'),p={name:"cs/zero-copy-network.md"};function D(B,e,c,_,m,P){const o=n("Mermaid");return E(),d("div",null,[e[2]||(e[2]=s('<h1 id="零拷贝网络" tabindex="-1">零拷贝网络 <a class="header-anchor" href="#零拷贝网络" aria-label="Permalink to &quot;零拷贝网络&quot;">​</a></h1><div class="epigraph"><p>零拷贝让包数据只被 DMA 一次：MSG_ZEROCOPY、sendfile、AF_XDP umem 或包头仅线性拷贝，负载留在页上。</p><footer>—— 据 Linux MSG_ZEROCOPY 文档；sendfile 实践；AF_XDP 对 umem 的说明</footer></div><p><a href="/cs/sendfile-splice">sendfile</a> 已从文件侧减拷。<a href="/cs/skbuff">sk_buff</a> 的 frags 是载体。<a href="/cs/rss-multiqueue">RSS</a> 解决 CPU。缺口是 <strong>网络零拷贝</strong> 的几条路径与完成通知——不是绝对零。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>send</code> 默认拷进 skb 线性区或内核页。<code>MSG_ZEROCOPY</code>：用户页钉住，协议用，完成用错误队列通知可改页。接收：<code>recvmmsg</code> 仍常拷；真正少拷是 mmap 包环、AF_XDP、或 GRO 后直接 splice 到文件。缺口：页必须对齐、不能立即重写；校验卸载与加密可能迫使拷贝。本课不把 TLS 内核卸载细节写完。</p><p><span class="marginnote">数字实例：发 1 GB 静态文件，普通路径要在用户缓冲与内核之间 memcpy 一到两次，纯 CPU 拷贝按 10 GB/s 算约耗 0.1–0.2 秒的核时间；sendfile/零拷贝把这段归零，只剩 DMA 与协议开销——带宽没变，省的是 CPU。</span></p><p><span class="marginnote">「零拷贝」统计上常是「少一次」。调试要用完成通知，否则数据竞争。与 O_DIRECT 同构：应用承担生命周期。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送静态文件：sendfile。发送用户缓冲：MSG_ZEROCOPY + 等 completion。接收旁路：AF_XDP 把 umem 填给驱动。对照 DPDK：全程用户 mbuf。对照 <a href="/cs/fs-mmap-coherence">mmap 文件</a>：文件零拷贝与网络零拷贝可在 sendfile 汇合。</p>',9)),(E(),r(A,null,{default:a(()=>[l(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E9%A1%B5%E6%88%96%E6%96%87%E4%BB%B6%E9%A1%B5%22%5D%20--%3E%20PIN%5B%22%E9%92%89%E9%A1%B5%22%5D%0A%20%20PIN%20--%3E%20DMA%5B%22%E7%BD%91%E5%8D%A1%20DMA%22%5D%0A%20%20CMP%5B%22%E5%AE%8C%E6%88%90%E9%80%9A%E7%9F%A5%22%5D%20--%3E%20UNPIN%5B%22%E6%89%8D%E5%8F%AF%E6%94%B9%E9%A1%B5%22%5D%0A%20%20COPY%5B%22%E6%99%AE%E9%80%9A%20send%22%5D%20--%3E%20SKB%5B%22%E5%86%85%E6%A0%B8%E6%8B%B7%E8%B4%9D%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>零拷贝把 CPU memcpy 从数据面拿掉，瓶颈回到 DMA 与协议状态。它不取消 <a href="/cs/socket-buffers">套接字缓冲</a> 的会计——记账仍按字节。不要写成网卡广告。与 XDP：XDP 改的是早处理，数据仍可在同一页上 TX。</p><p><span class="marginnote">直觉类比：零拷贝像把包裹&quot;原箱直发&quot;——你不拆开重新装箱，只在箱面贴张新运单（包头），交给快递（网卡）直接拉走。代价是箱子在签收（完成通知）前不许动；提前改箱内东西，寄出去的就是被改过的货。</span></p><p><span class="marginnote">常见误区：初学者容易以为换了 sendfile/MSG_ZEROCOPY 就&quot;绝对零拷贝&quot;。实际 TLS 加密、校验和卸载失败、页不对齐等都会让内核静默回退成拷贝——省没省成，要靠完成通知与计数验证，不能只看 API 名字。</span></p>',4)),(E(),r(A,null,{default:a(()=>[l(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%E6%8F%90%E4%BA%A4%E5%8F%91%E9%80%81%22%5D%20--%3E%20D%7B%22%E8%B5%B0%E5%93%AA%E6%9D%A1%E5%8F%91%E9%80%81%E8%B7%AF%E5%BE%84%22%7D%0A%20%20D%20--%3E%20NZ%5B%22MSG_ZEROCOPY%EF%BC%9A%E9%A1%B5%E9%92%89%E4%BD%8F%22%5D%0A%20%20D%20--%3E%20SF%5B%22sendfile%EF%BC%9A%E6%96%87%E4%BB%B6%E9%A1%B5%E7%9B%B4%E5%8F%91%22%5D%0A%20%20D%20--%3E%20CP%5B%22%E6%99%AE%E9%80%9A%20send%EF%BC%9A%E6%8B%B7%E8%BF%9B%E5%86%85%E6%A0%B8%22%5D%0A%20%20NZ%20--%3E%20DMA%5B%22%E7%BD%91%E5%8D%A1%20DMA%20%E8%B4%9F%E8%BD%BD%E9%A1%B5%22%5D%0A%20%20SF%20--%3E%20DMA%0A%20%20CP%20--%3E%20CP2%5B%22CPU%20%E6%90%AC%E8%BF%90%E5%90%8E%E5%86%8D%20DMA%22%5D%0A%20%20DMA%20--%3E%20ACK%5B%22%E5%AE%8C%E6%88%90%E9%80%9A%E7%9F%A5%E5%9B%9E%E9%94%99%E8%AF%AF%E9%98%9F%E5%88%97%22%5D%0A%20%20ACK%20--%3E%20REUSE%5B%22%E6%AD%A4%E5%90%8E%E6%89%8D%E5%8F%AF%E9%87%8D%E7%94%A8%E7%BC%93%E5%86%B2%22%5D%0A%20%20CP2%20--%3E%20REUSE%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=s('<p>失败回退到拷贝必须正确，否则静默损坏。</p><p>实现上：MSG_ZEROCOPY 的完成通知走错误队列，应用必须读，否则不能重用缓冲。页必须 page-aligned 且生命周期覆盖 DMA。校验与加密卸载失败会静默拷贝。 读法上只引用<a href="/cs/rss-multiqueue">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>零拷贝网络</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 NIC 的 header-data split。不保证虚拟机 vhost 零拷贝与客户页的 IOMMU 映射总成功。下一课把「绕过 TCP 的传输」接到 OS：RDMA。</p><p>版本字段会变，课序钉的是机制对象「零拷贝网络」，不是某一主线内核的结构体名。 后课默认：发送路径可钉用户/文件页 DMA。RDMA 在 OS 中的队列对与内存注册，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>零拷贝靠钉页与 DMA，完成前不能改缓冲。</li><li>sendfile、MSG_ZEROCOPY、AF_XDP 是不同接头。</li><li>RDMA 是下一课。</li><li>出处：Linux <code>MSG_ZEROCOPY</code>；AF_XDP；sendfile。</li></ul>',9))])}const C=i(p,[["render",D]]);export{u as __pageData,C as default};
